scripts.script:
let poisoned= args.actor.hasCondition("poisoned")
if (poisoned)
{
    let poisoned = args.actor.hasCondition("poisoned")
    if (poisoned)
    {
        poisoned.system.scriptData = []
        poisoned.system._scripts = null;
    }

}

let fatigued = args.actor.hasCondition("fatigued")
if (fatigued)
{
    let fatigued = args.actor.hasCondition("fatigued")
    if (fatigued)
    {
        fatigued.system.scriptData = fatigued.system.scriptData.filter(s => s.trigger != "dialog")
        fatigued.system._scripts = null;
    }
}

let effects = [this.actor.hasCondition("poisoned")].filter(i => i);

effects = effects.concat(Array.from(this.actor.allApplicableEffects()).filter(e => ["disease", "critical", "injury", "mutation"].includes(e.item?.type)));
this.effect.updateSource({"flags.wfrp4e.effectsDisabled" : effects.map(i => i.uuid)});

if (effects.length)
{
	this.script.notification(`Disabled ${effects.length} Effects`)
}

effects.forEach(e => e.update({disabled : true}))

let effectIds = this.effect.flags.wfrp4e?.effectsDisabled || [];

let effects = await Promise.all(effectIds.map(fromUuid));

effects.forEach(e => e.update({disabled : false}))
